#!/usr/bin/python3
"""New flex shorthand compilation/resolution cost over prebuilt components.
Seven frozen release processes. Numeric flex cases visit all three assignments;
a pending shorthand group resolves once. Separate longhands are descriptive
controls; no before implementation of the accepted shorthand exists. Excludes
syntax construction, cascade, style/layout, GUI, GPU and site acceptance.
"""
import hashlib,json,os,select,statistics,subprocess
from pathlib import Path
root=Path('/var/tmp/olo-browser-stripe/flex-css/cost');binary=root/'properties-after'
allowed=sorted(os.sched_getaffinity(0))
def frequency(cpu):
 p=Path(f'/sys/devices/system/cpu/cpu{cpu}/cpufreq/cpuinfo_max_freq')
 return int(p.read_text())if p.exists()else 0
cpu=max(allowed,key=frequency);os.sched_setaffinity(0,{cpu})
def context():
 procs={}
 for p in Path('/proc').iterdir():
  if p.name.isdigit():
   try:
    name=(p/'comm').read_text().strip()
    if name in ('cargo','rustc'):procs[p.name]=name
   except OSError:pass
 return dict(loadavg=os.getloadavg(),build_processes=procs)
rows,discarded,waits=[],[],[]
for repeat in range(7):
 while True:
  before=context();compilers=[p for p,n in before['build_processes'].items()if n=='rustc']
  if compilers:
   waits.append(before);fds=[]
   try:
    for pid in compilers:
     try:fds.append(os.pidfd_open(int(pid)))
     except ProcessLookupError:pass
    if fds:select.select(fds,[],[],20)
   finally:
    for fd in fds:os.close(fd)
   continue
  rss=root/'properties.rss'
  data=json.loads(subprocess.check_output(['/usr/bin/time','-f','%M','-o',str(rss),str(binary),'20000','flex'],text=True))
  assert data['flex_mode'] and len(data['cases'])==17
  observation=dict(repeat=repeat,before_context=before,after_context=context(),rss_kib=int(rss.read_text()),**data)
  if 'rustc'in observation['after_context']['build_processes'].values():discarded.append(observation);continue
  rows.append(observation);print(repeat,flush=True);break
summary=[]
for c in rows[0]['cases']:
 group=[x for r in rows for x in r['cases']if(x['property'],x['source'])==(c['property'],c['source'])]
 summary.append(dict(property=c['property'],source=c['source'],longhands=c['longhands'],**{k:statistics.median(x[k]for x in group)for k in ['compile_drop_us','first_compile_us','resolve_us','first_resolve_us']}))
Path('docs/browser/measurements/2026-11-06-stripe-flex-shorthand-parse-cost.json').write_text(json.dumps(dict(scope=__doc__,cpu=cpu,allowed_cpus=allowed,binary_sha256=hashlib.sha256(binary.read_bytes()).hexdigest(),script=Path(__file__).read_text(),observations=rows,discarded=discarded,build_waits=waits,summary=summary),indent=2)+'\n')
print(json.dumps(summary),flush=True)
